from django.db import migrations, models

WON_GAIN = ("battle_win", "cashout_refund")
BONUS_GAIN = ("signup", "stage_complete", "admin")


def split_gold(gold, won, bonus, amount, reason, bonus_part=0):
    """GoldTransaction.split_gold-ийн хуулбар (migration загварын классын аргыг ашиглаж чадахгүй)."""
    if amount > 0:
        if reason in WON_GAIN:
            part = min(max(0, bonus_part), amount)
            won += amount - part
            bonus += part
        elif reason in BONUS_GAIN:
            bonus += amount
    elif amount < 0:
        spend = -amount
        if reason == "cashout":
            won = max(0, won - spend)
        else:
            paid = max(0, gold - won - bonus)
            take = min(spend, bonus)
            bonus -= take
            spend -= take
            spend -= min(spend, paid)
            won = max(0, won - spend)
    gold += amount
    won = min(won, gold)
    bonus = min(bonus, gold - won)
    return gold, won, bonus


def recount_gold(apps, schema_editor):
    """Бүх гүйлгээг цаг хугацааны дарааллаар шинэ дүрмээр дахин тооцно: үе шатны шагнал хожсонд орохгүй, эхлэлийн
    болон шагналын Gold тулаанд шилжихдээ урамшуулал хэвээр (ялагдагчийн тэр мөчийн урамшууллаас)."""
    Player = apps.get_model("game", "Player")
    GoldTransaction = apps.get_model("game", "GoldTransaction")
    state = {}    # тоглогч -> (gold, won, bonus)
    pending = {}  # "battle:<өрөө>:<тулаан>" -> ялагдагчийн урамшууллаас шилжсэн хэсэг
    rows = GoldTransaction.objects.order_by("created", "id").values_list("player_id", "amount", "reason", "ref")
    for player_id, amount, reason, ref in rows.iterator():
        gold, won, bonus = state.get(player_id, (0, 0, 0))
        part = 0
        if reason == "battle_loss" and ref.endswith(":loss"):
            pending[ref[:-len(":loss")]] = min(-amount, bonus)
        elif reason == "battle_win" and ref.endswith(":win"):
            part = pending.pop(ref[:-len(":win")], 0)
        state[player_id] = split_gold(gold, won, bonus, amount, reason, part)
    for player in Player.objects.all().iterator():
        _, won, bonus = state.get(player.pk, (player.gold, 0, 0))
        won = min(won, player.gold)
        bonus = min(bonus, player.gold - won)
        if won != player.won_gold or bonus != player.bonus_gold:
            Player.objects.filter(pk=player.pk).update(won_gold=won, bonus_gold=bonus)


